lib_code='''def rot90(grid):
    """The grid rotated 90 degrees clockwise."""
    return [list(r) for r in zip(*grid[::-1])]

def rot270(grid):
    """The grid rotated 90 degrees counterclockwise."""
    return [list(r) for r in zip(*grid)][::-1]

def rot180(grid):
    """The grid rotated 180 degrees."""
    return [r[::-1] for r in grid[::-1]]

def kaleidoscope(grid):
    """The grid tiled 2x2: top-right rotated 90, bottom-left rotated 270, bottom-right rotated 180."""
    n = len(grid)
    r90, r270, r180 = rot90(grid), rot270(grid), rot180(grid)
    return [grid[i] + r90[i] for i in range(n)] + [r270[i] + r180[i] for i in range(n)]
